# System.Runtime.Intrinsics.X86.Sse — packed and scalar single arithmetic. A one-operand
# scalar form (SqrtScalar(value)) is the intrinsic itself; the two-operand form
# (SqrtScalar(upper, value)) has no C intrinsic: the instruction writes lane 0 from
# `value` into `upper`, which _mm_move_ss over the one-operand result reproduces bit for
# bit. The reciprocal estimates are hardware approximations, so they carry no reference.
target = sse
Add(v128f32,v128f32) @ref(Vector128.Add($0, $1)) = _mm_add_ps($0, $1)
AddScalar(v128f32,v128f32) @ref($0.WithElement(0, $0.GetElement(0) + $1.GetElement(0))) = _mm_add_ss($0, $1)
Subtract(v128f32,v128f32) @ref(Vector128.Subtract($0, $1)) = _mm_sub_ps($0, $1)
SubtractScalar(v128f32,v128f32) @ref($0.WithElement(0, $0.GetElement(0) - $1.GetElement(0))) = _mm_sub_ss($0, $1)
Multiply(v128f32,v128f32) @ref(Vector128.Multiply($0, $1)) = _mm_mul_ps($0, $1)
MultiplyScalar(v128f32,v128f32) @ref($0.WithElement(0, $0.GetElement(0) * $1.GetElement(0))) = _mm_mul_ss($0, $1)
Divide(v128f32,v128f32) @ref(Vector128.Divide($0, $1)) = _mm_div_ps($0, $1)
DivideScalar(v128f32,v128f32) @ref($0.WithElement(0, $0.GetElement(0) / $1.GetElement(0))) = _mm_div_ss($0, $1)
Max(v128f32,v128f32) @ref(Vector128.Max($0, $1)) = _mm_max_ps($0, $1)
MaxScalar(v128f32,v128f32) @ref($0.WithElement(0, MathF.Max($0.GetElement(0), $1.GetElement(0)))) = _mm_max_ss($0, $1)
Min(v128f32,v128f32) @ref(Vector128.Min($0, $1)) = _mm_min_ps($0, $1)
MinScalar(v128f32,v128f32) @ref($0.WithElement(0, MathF.Min($0.GetElement(0), $1.GetElement(0)))) = _mm_min_ss($0, $1)
Sqrt(v128f32) @ref(Vector128.Sqrt($0)) = _mm_sqrt_ps($0)
SqrtScalar(v128f32) @ref($0.WithElement(0, MathF.Sqrt($0.GetElement(0)))) = _mm_sqrt_ss($0)
SqrtScalar(v128f32,v128f32) @ref($0.WithElement(0, MathF.Sqrt($1.GetElement(0)))) = _mm_move_ss($0, _mm_sqrt_ss($1))
Reciprocal(v128f32) = _mm_rcp_ps($0)
ReciprocalScalar(v128f32) = _mm_rcp_ss($0)
ReciprocalScalar(v128f32,v128f32) = _mm_move_ss($0, _mm_rcp_ss($1))
ReciprocalSqrt(v128f32) = _mm_rsqrt_ps($0)
ReciprocalSqrtScalar(v128f32) = _mm_rsqrt_ss($0)
ReciprocalSqrtScalar(v128f32,v128f32) = _mm_move_ss($0, _mm_rsqrt_ss($1))
